@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@implements IAsyncDisposable
@inject IShipmentService ShipmentService
@inject ILogger<TrackShipment> Logger

@if (error is not null)
{
    <div class="alert alert-danger">
        <p>@error</p>
        <button @onclick="LoadAsync">Retry</button>
    </div>
}
else if (shipment is null)
{
    <div class="loading-placeholder">
        <p><em>Loading shipment @TrackingNumber…</em></p>
    </div>
}
else
{
    @if (isLoading)
    {
        <p><em>Refreshing…</em></p>
    }

    <h2>Shipment @shipment.TrackingNumber</h2>
    <dl>
        <dt>Status</dt>
        <dd>@shipment.Status</dd>
        <dt>Current Location</dt>
        <dd>@shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h3>Tracking History</h3>
    <ul>
        @foreach (var update in shipment.StatusUpdates)
        {
            <li>
                <strong>@update.Timestamp.ToString("g")</strong> —
                @update.Description (@update.Location)
            </li>
        }
    </ul>
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = default!;

    private CancellationTokenSource? cts;
    private string? loadedTrackingNumber;
    private ShipmentDetails? shipment;
    private bool isLoading;
    private string? error;

    protected override async Task OnParametersSetAsync()
    {
        if (TrackingNumber == loadedTrackingNumber)
        {
            return;
        }

        loadedTrackingNumber = TrackingNumber;
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }

        cts = new CancellationTokenSource();
        var cancellationToken = cts.Token;

        error = null;
        isLoading = true;

        try
        {
            var result = await ShipmentService.GetShipmentAsync(TrackingNumber, cancellationToken);

            if (result is null)
            {
                error = "Shipment not found. Please check the tracking number and try again.";
            }
            else
            {
                shipment = result;
            }
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            // Self-cancellation (parameter change or disposal) — do nothing
        }
        catch (OperationCanceledException ex)
        {
            Logger.LogWarning(ex, "Request timed out for tracking number {TrackingNumber}", TrackingNumber);
            error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to load shipment {TrackingNumber}", TrackingNumber);
            error = "Something went wrong loading the shipment. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

